// ---- Custom tools (P1) manage panel ----------------------------------------
// Lists persisted custom tools and lets the user define/remove them. define and
// remove MUTATE the registry, so they run through /api/custom_tools endpoints
// that gate on trust mode or a bound Telegram (fail-closed otherwise â€” do those
// in chat where the in-app approval dialog appears). No template literals here:
// this script is embedded in a TS template string, so the interpolation
// sigil must be avoided.
const btnCustomTools = document.getElementById('btn-custom-tools');
if (btnCustomTools) btnCustomTools.addEventListener('click', async () => {
  pnTitle.textContent = 'ðŸ›  Custom tools';
  pnBody.textContent = 'Loadingâ€¦';
  panel.classList.remove('hidden');
  const append = (parent, tag, text) => { const e = document.createElement(tag); e.textContent = text; parent.appendChild(e); return e; };
  try {
    const r = await fetch('/api/custom_tools', { headers: authHeaders() });
    const j = await r.json();
    const tools = (j && j.tools) || [];
    const host = document.createElement('div');
    host.style.fontFamily = 'var(--mono)';
    host.style.whiteSpace = 'pre-wrap';
    if (tools.length === 0) {
      append(host, 'div', '(no custom tools defined yet â€” use the form below)');
    } else {
      for (const t of tools) {
        const row = document.createElement('div');
        row.style.display = 'flex';
        row.style.alignItems = 'center';
        row.style.gap = '8px';
        row.style.margin = '4px 0';
        append(row, 'span', t.name + '  (' + t.approval + ')  ' + (t.description || '') + '  â†’  ' + (t.command || []).join(' '));
        const rm = document.createElement('button');
        rm.textContent = 'Remove';
        rm.style.marginLeft = 'auto';
        row.appendChild(rm);
        rm.addEventListener('click', async () => {
          const res = await fetch('/api/custom_tools/remove', {
            method: 'POST',
            headers: { 'content-type': 'application/json', ...authHeaders() },
            body: JSON.stringify({ name: t.name }),
          });
          const jj = await res.json();
          pnBody.textContent = jj.content || jj.error || '(no output)';
          location.reload();
        });
        host.appendChild(row);
      }
    }
    const sep = document.createElement('div');
    sep.style.borderTop = '1px solid var(--border)';
    sep.style.margin = '10px 0';
    host.appendChild(sep);
    append(host, 'div', 'Define a new custom tool:');
    const field = (label) => {
      const wrap = document.createElement('div');
      wrap.style.margin = '4px 0';
      const input = document.createElement('input');
      input.style.background = 'var(--bg2)';
      input.style.color = 'var(--fg)';
      input.style.border = '1px solid var(--border)';
      input.style.borderRadius = '4px';
      input.style.padding = '4px 6px';
      input.style.fontFamily = 'var(--mono)';
      input.style.width = '100%';
      input.placeholder = label;
      wrap.appendChild(input);
      host.appendChild(wrap);
      return input;
    };
    const fName = field('name (letters, digits, _ -)');
    const fDesc = field('description');
    const fCmd = field('command â€” argv, space-separated (e.g. python script.py)');
    const fSchema = field('input_schema JSON (optional; default {type:object})');
    const fAppr = field('approval: ask | auto (default ask)');
    const go = document.createElement('button');
    go.textContent = 'Define';
    host.appendChild(go);
    go.addEventListener('click', async () => {
      let schema = { type: 'object', properties: {} };
      if (fSchema.value.trim()) {
        try { schema = JSON.parse(fSchema.value.trim()); }
        catch (err) { pnBody.textContent = 'âš  input_schema must be valid JSON: ' + (err instanceof Error ? err.message : String(err)); return; }
      }
      const res = await fetch('/api/custom_tools', {
        method: 'POST',
        headers: { 'content-type': 'application/json', ...authHeaders() },
        body: JSON.stringify({
          name: fName.value.trim(),
          description: fDesc.value.trim(),
          command: fCmd.value.trim().split(/s+/).filter(Boolean),
          input_schema: schema,
          approval: fAppr.value.trim().toLowerCase() === 'auto' ? 'auto' : 'ask',
        }),
      });
      const jj = await res.json();
      pnBody.textContent = jj.content || jj.error || '(no output)';
      location.reload();
    });
    pnBody.textContent = '';
    pnBody.appendChild(host);
  } catch (e) {
    pnBody.textContent = 'âš  ' + (e instanceof Error ? e.message : String(e));
  }
});

// ---- Forget a learned source (B6) ----
// Knowledge could be added but never removed. A dropdown rather than a free-text
// box on purpose: the tool resolves a partial reference, and a short or ambiguous
// reference deletes nothing and asks you to be specific. Picking the exact source
// means that ambiguity cannot arise here at all.
const forgetModal = document.getElementById('forget-modal');
