// ---- Trust mode ---------------------------------------------------------
// Lets the user stop answering "Allow" for ordinary tools. OFF by default and
// never persisted, so a restart always comes back fail-closed. The server
// decides what is exempt; the button just reflects the state and warns about
// what trust mode will NOT cover.
//
// ON/OFF ONLY â€” no timed windows, no countdown. Clicking the button flips
// the switch: on -> off immediately, off -> on immediately.
const btnTrust = document.getElementById('btn-trust');
let trustOn = false;
let trustAlwaysAsk = [];
function paintTrust() {
  if (!btnTrust) return;
  const label = trustOn ? 'ðŸ›¡ Trust mode: ON' : 'ðŸ›¡ Trust mode: OFF';
  const tip = trustOn
    ? 'Trust mode is ON â€” ordinary tools run without asking. Still always asks: ' +
      (trustAlwaysAsk.join(', ') || 'nothing') + '. Click to turn OFF.'
    : 'Trust mode is OFF â€” every approval-gated tool asks. Click to turn ON until you turn it off or BlackRose restarts.';
  btnTrust.textContent = label;
  btnTrust.classList.toggle('on', trustOn);
  btnTrust.title = tip;
}
async function loadTrust() {
  try {
    const r = await fetch('/api/trust', { headers: authHeaders() });
    const d = await r.json();
    // The server returns { on, alwaysAsk } â€” the same key the POST body uses.
    // Reading d.trust here made the button permanently stuck at OFF.
    trustOn = d.on === true;
    trustAlwaysAsk = Array.isArray(d.alwaysAsk) ? d.alwaysAsk : [];
  } catch { trustOn = false; }
  paintTrust();
}
if (btnTrust) {
  btnTrust.addEventListener('click', async () => {
    // Flip the switch: on -> off, off -> on. No dialog, no duration to pick.
    const next = !trustOn;
    try {
      const r = await fetch('/api/trust', {
        method: 'POST',
        headers: { 'content-type': 'application/json', ...authHeaders() },
        body: JSON.stringify({ on: next }),
      });
      const d = await r.json();
      trustOn = d.on === true;
      trustAlwaysAsk = Array.isArray(d.alwaysAsk) ? d.alwaysAsk : [];
    } catch { /* leave the state as it was */ }
    paintTrust();
    const tail = ' Still always asks: ' + (trustAlwaysAsk.join(', ') || 'nothing');
    el('activity', trustOn
      ? 'ðŸ›¡ Trust ON â€” ordinary tools run without asking until you turn it off or BlackRose restarts.' + tail
      : 'ðŸ›¡ Trust mode OFF â€” tools ask again');
  });
  loadTrust();
}

// ---- Browser login / cookie source (B11) ----
// Reels and other signin-walled posts need a browser session. Until now the only
// way to give BlackRose one was the BLACKROSE_YTDLP_ARGS environment variable,
// which a desktop user has no natural way to set â€” so the capability existed in a
// comment and an error message and nowhere else. The choice is persisted server
// side and read fresh on every watch_video / instagram scrape.
//
// NO APOSTROPHES anywhere in this block: this JS lives inside a template literal
// in the TS source, and an escaped quote is consumed when the template evaluates,
// which has shipped broken page JS twice.
(function wireCookieSource() {
  const sel = document.getElementById('cookie-source');
  const fileRow = document.getElementById('cookie-file-row');
  const fileInp = document.getElementById('cookie-file');
  const note = document.getElementById('cookie-note');
  const save = document.getElementById('btn-cookie-save');
  // Guarded element-by-element: a markup rename must not break the whole script.
  if (!sel || !save) return;
  let chromeNote = '';

  function paintCookie(mode) {
    const isFile = mode === 'file';
    if (fileRow) fileRow.style.display = isFile ? '' : 'none';
    if (note) {
      note.textContent = mode === 'chrome'
        ? chromeNote
        : (mode === 'file'
          ? 'yt-dlp reads this file at download time. BlackRose stores the PATH only, never cookie contents.'
          : (mode === 'firefox'
            ? 'Reads the signed-in Firefox profile at download time. Log in to Firefox first.'
            : 'No cookies: public posts work, signin-walled posts will not.'));
    }
  }

  async function loadCookies() {
    try {
      const r = await fetch('/api/cookies', { headers: authHeaders() });
      const d = await r.json();
      if (typeof d.chromeNote === 'string') chromeNote = d.chromeNote;
      const mode = d.source && d.source.mode ? String(d.source.mode) : 'none';
      sel.value = mode;
      if (fileInp && d.source && d.source.path) fileInp.value = String(d.source.path);
      paintCookie(mode);
    } catch (e) {
      if (note) note.textContent = 'Could not read the saved browser login choice.';
    }
  }

  sel.addEventListener('change', () => paintCookie(sel.value));
  save.addEventListener('click', async () => {
    save.disabled = true;
    try {
      const res = await fetch('/api/cookies', {
        method: 'POST',
        headers: { 'content-type': 'application/json', ...authHeaders() },
        body: JSON.stringify({ mode: sel.value, path: fileInp ? fileInp.value.trim() : '' }),
      });
      const d = await res.json();
      if (!res.ok || !d.ok) throw new Error(d.error || ('HTTP ' + res.status));
      if (typeof d.chromeNote === 'string') chromeNote = d.chromeNote;
      paintCookie(sel.value);
      el('activity', 'ðŸ”’ Browser login saved: ' + sel.value +
        (sel.value === 'chrome' ? ' (expected to fail â€” Chrome cookies cannot be read on Windows)' : ''));
    } catch (err) {
      if (note) note.textContent = 'Not saved: ' + (err instanceof Error ? err.message : String(err));
    } finally {
      save.disabled = false;
    }
  });
  loadCookies();
})();

